"""Generate LICENSES.md for the episode from the per-file *.source.json sidecars (used assets only)."""
import json, os, re, glob
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
USED = {
 'p_mine_lamco': ('D · 12.0–13.5 s', 'Station 2 «استخراج»: real open-pit iron-ore mine (LAMCO, Liberia, archival)', 'صورة حقيقية · منجم حديد مكشوف'),
 'v_furnace': ('D · 13.3–14.3 s', 'Station 3 «صهر»: real blast-furnace / molten iron footage', 'لقطات حقيقية · فرن صهر'),
 'v_staubli': ('D · 14.1–15.1 s', 'Station 4 «تصنيع»: real industrial robot (pick-and-place)', 'لقطات حقيقية · روبوت صناعي'),
 'p_bmw_bodyshop': ('D · 15.0–16.3 s', 'Station 5 «تجميع»: real robotic car body shop', 'صورة حقيقية · خط تجميع آلي'),
 'p_car_carrier': ('D · 16.4–18.9 s', 'Station 6 «توصيل»: real (human-driven) car carrier — contrasts with the illustrated autonomous truck', 'صورة حقيقية · اليوم بسائق'),
 'v_robot_lab': ('E · 22.3–23.9 s', '«ومين بطوّرها؟»: real autonomous lab robot (A-Lab study)', 'لقطات حقيقية · مختبر آلي'),
 'v_wind_vertical': ('F · 24.0–27.5 s', '«وحتى الطاقة»: real wind turbine', 'لقطات حقيقية · طاقة الرياح'),
 'v_solar': ('F · 25.2–27.5 s', 'real solar (agrivoltaic) plant', 'لقطات حقيقية · طاقة شمسية'),
 'v_harvester': ('H · 33.7–36.0 s', '«بالأكل»: combine harvester', 'لقطات حقيقية'),
 'v_3dhouse': ('H · 34.2–36.0 s', '«والبيوت»: 3D-printed house (TECLA)', 'لقطات حقيقية'),
 'v_looms': ('H · 34.7–36.0 s', '«والملابس»: power looms (Queen Street Mill)', 'لقطات حقيقية'),
 'v_tablet_press': ('H · 35.3–36.0 s', '«والدوا»: rotary tablet press', 'لقطات حقيقية'),
 'p_al_ingots': ('L · 48.3–50.8 s', '«معادن بتصنع منها أشياء»: metal ingots (archival)', 'صورة حقيقية · سبائك معدن'),
 'p_pylon': ('L · 50.8–53.3 s', '«وطاقة…»: high-voltage transmission tower', 'صورة حقيقية · شبكة كهربا'),
}
clean = lambda s: re.sub(r'\s+', ' ', re.sub('<[^>]+>', '', s or '')).strip()
rows, unused = [], []
for f in sorted(glob.glob(os.path.join(HERE, 'raw', '*.source.json'))):
    d = json.load(open(f, encoding='utf-8'))
    if d['key'] not in USED: unused.append(d); continue
    when, what, tag = USED[d['key']]
    rows.append((d, when, what, tag))
L = ['# Media sources & licences — «المصاري رح يبطل إلها قيمة» (NO MONEY ANYMORE)', '',
     'Generated by `03_MEDIA/scripts/make_licenses.py` from the sidecar `*.source.json` written at download time',
     '(licence, author and URLs read live from the Wikimedia Commons API). Every real image/clip carries an on-screen credit',
     '(kind of evidence · author · licence). Clips were trimmed/transcoded to H.264 for editing (`_BRAND_SYSTEM/public/episodes/no-money/media/`);',
     'originals are kept untouched in `03_MEDIA/raw/`.', '', '## 1. Real-world media used (all Wikimedia Commons)', '']
for d, when, what, tag in sorted(rows, key=lambda r: r[1]):
    L += [f"### {d['key']} — {what}",
          f"- **Where in the video:** {when} · on-screen tag «{tag}»",
          f"- **File page:** {d['page']}",
          f"- **Downloaded from:** {d.get('download_url')} ({d.get('downloaded_variant', 'original file')})",
          f"- **Author / rights holder:** {clean(d.get('author'))}" + (f" — credit: {clean(d.get('credit'))[:160]}" if d.get('credit') else ''),
          f"- **Licence:** {d['licence']} ({d.get('licence_url') or 'n/a'}) · attribution required: {d.get('attribution_required')}",
          f"- **Local file:** `03_MEDIA/raw/{os.path.basename(d['local_path'])}` · sha256 `{d['sha256'][:16]}…` · fetched {d['fetched']}", '']
L += ['## 2. Downloaded for review but NOT used', '']
for d in unused:
    L.append(f"- {d['key']}: {d['title'][5:]} — {d['licence']} (rejected: weaker relevance, fence obstruction, people in frame, or redundant)")
L += ['', '## 3. Original / in-house', '',
      '- **Narration:** the creator\'s own recording (`01_AUDIO/Original/narration_original.m4a`, sha256 `88004a14…67051`), unedited.',
      '- **All illustrations, diagrams, typography, paper textures, the fictional banknote:** original, generated in code (Remotion/SVG + `_BRAND_SYSTEM/tools/make_textures.py`). The banknote is fictional (no real currency, no portrait).',
      '- **Music and all sound effects:** original synthesis (`04_SFX_MUSIC/audio_design.py`); no samples or third-party music.',
      '- **Fonts (SIL Open Font License 1.1):** Alexandria, Baloo Bhaijaan 2, Lalezar (Google Fonts repository), IBM Plex Sans Arabic, JetBrains Mono.',
      '- **Software:** Remotion 4.0.537 — Free License (eligible: individual creator / company ≤ 3 employees; see remotion LICENSE.md). FFmpeg, Python (numpy/scipy/Pillow/faster-whisper).',
      '', '## 4. Notes on obligations', '',
      '- **CC BY / CC BY-SA:** attribution is shown on screen at each use and listed here. Five used items are **ShareAlike** (p_mine_lamco, v_furnace, p_bmw_bodyshop, v_looms, v_tablet_press). If a platform or partner treats the edited video as an *adaptation* of those works, ShareAlike would require the adapted portions to be offered under a compatible licence. If that is a concern for commercial distribution, those five items can be swapped for CC0/CC BY alternatives and only the affected frame ranges re-rendered.',
      '- **Trademarks:** no third-party logos are shown as marks; the BMW photo is an editorial depiction of a body shop credited to its uploader (BMW Werk Leipzig).',
      '- **People:** no identifiable faces are used.']
open(os.path.join(os.path.dirname(HERE), 'LICENSES.md'), 'w', encoding='utf-8').write('\n'.join(L) + '\n')
print('written', len(rows), 'used,', len(unused), 'unused')
